 auto& RA=K.personalityRelation(PA,a);auto& RB=K.personalityRelation(PB,a);check(personalitySalary(K,B,a,100)<personalitySalary(K,A,a,100),"loyal player asks less than ambitious player");RA.stagnantSeasons=2;RA.attachment=20;RB.stagnantSeasons=2;K.season.now=.1;K.personalityMonth(a);check(RA.transferRequested&&!RB.transferRequested,"stagnation frustrates ambitious disloyal player without forcing departure");std::string msg;check(!K.personalityContract(A,a,3,msg)&&K.personalityContract(B,a,3,msg),"loyal player easier to renew");int old=K.year;RA.lastTier=3;g_world.teams[a].lastTier=2;K.personalitySeasonEnd();check(!RA.transferRequested&&RA.stagnantSeasons==0,"promotion cancels frustrated ambition");K.personalitySeasonEnd();check(RA.seasons==1,"annual effects cannot run twice");g_world.teams[a].lastTier=0;K.year=old;
 PB.traits.loyalty=20;PB.traits.ambition=90;PB.traits.sensitivity=95;RB.lastDecision=-1;B.morale=70;K.personalityDecision(B,a,0);int mood=B.morale;check(mood<70,"sensitive player reacts to bench");K.personalityDecision(B,a,0);check(B.morale==mood,"decision reactions cannot accumulate every click or frame");A.morale=70;K.personalityDecision(A,a,0);check(A.morale==70,"calm player accepts same bench decision");PB.traits.loyalty=95;RB.attachment=80;RB.seasons=5;check(personalityCaptainScore(K,B,a)>personalityCaptainScore(K,A,a),"leadership loyalty and history guide captaincy");K.personalityCaptain(a,B.id);check(g_world.teams[a].captainPid==B.id&&RB.captaincy&&RB.fanPopularity>=20,"captaincy affects attachment popularity and group influence");check(personalityLegendBonus(K,B.id,a)>0&&personalityLegendBonus(K,A.id,a)==0,"loyal historical leader has modest museum bonus");check(supporterFanPopularity(K,a,B.id)>=RB.fanPopularity,"personality connects to supporters");printf("PASS personality C/D/E/G: ambition, loyalty, emotions, captain and supporters\n");
 Player young=specimen(g_world.nextPid++,"Jeune accompagné"),mentor=specimen(g_world.nextPid++,"Mentor professionnel");young.age=18;mentor.age=32;auto& T=g_world.teams[a];T.squad.push_back(young);T.squad.push_back(mentor);auto& PY=K.personalityPlayer(young,a);auto& PM=K.personalityPlayer(mentor,a);PY.traits.professionalism=40;PY.traits.leadership=25;PM.traits.professionalism=95;PM.traits.leadership=95;check(K.personalityMentor(a,young.id,mentor.id,msg),"valid experienced professional mentor");check(!K.personalityMentor(a,young.id,young.id,msg),"self mentorship rejected");int prof=PY.traits.professionalism;K.season.now=12.7;K.personalityMonth(a);check(PY.traits.professionalism==prof+1,"mentorship improves slowly");K.personalityMonth(a);check(PY.traits.professionalism==prof+1,"same month cannot farm mentorship");
