 K.opts=Career::Opts();K.opts.lite=1;K.newClubCareer(district,2026);check(!K.personalityEnabled()&&K.personalities.players.empty()&&personalityTrainingMultiplier(K,B)==1,"simple mode remains free of psychological management");
 K.opts=Career::Opts();K.newClubCareer(district,2026);for(int n=0;n<10;n++){int p,q,g;check(K.tierOfTeam(K.userTeam,&p,&q,&g)>=0,"club enrolled each year");int selected=K.pyramids[p].pools[q].comps[g];for(int ci=0;ci<(int)K.season.comps.size();ci++)if(ci!=selected){K.season.comps[ci].done=true;for(auto& st:K.season.comps[ci].stages)st.finished=true;}K.season.advance(true);check(K.season.finished,"selected championship finishes");K.mgr.noSack=true;K.mgr.budget=100000;int year=K.year;K.endSeason();check(K.year==year+1,"real annual transition");for(auto& pair:K.personalities.players){auto& P=pair.second;check(P.events.size()<=60&&P.relations.size()<=80,"bounded personality history");for(int i=0;i<10;i++)check(personalityTrait(P.traits,i)>=0&&personalityTrait(P.traits,i)<=100,"bounded traits over ten seasons");}printf("PASS personality year %d (%zu profiles)\n",K.year,K.personalities.players.size());}
